preConditionHook:
// Brooks stage 1 of the bull-trend weakening checklist: every one of the last
// barCount bars closed up, and each body is strictly smaller than the body of
// the bar before it. The comparison spans two bars, so no single-bar body rule
// can express it, and no pair of panes can either.
//
// All-of-N, written the way StrongTrendBarRun writes it -- start true and let
// any failing bar clear the flag -- so the loop runs unconditionally and
// EasyLanguage's lack of short-circuiting cannot matter. Both sides are
// computed here rather than in the conditions for the same reason.
//
// The pair comparison is guarded by kk <= barCount - 2 INSIDE the single loop
// rather than run as a second loop over 0..barCount-2, so no loop is ever
// asked to run with a limit below its start. Deepest bar read is therefore
// barCount - 1.
//
// Bodies are compared as DIFFERENCES, never as a ratio: EL raises a runtime
// divide-by-zero and a doji body of exactly 0 is legal data.
//
// The flags are class members and persist across bars; both are reset at the
// top of the hook rather than relied on to start true.
shrinkUp = true;
shrinkDown = true;
for (kk = 0; kk < (int)barCount; ++kk) {
    if (el_le(close[kk], open[kk])) shrinkUp = false;
    if (el_ge(close[kk], open[kk])) shrinkDown = false;
    if (kk <= (int)barCount - 2) {
        if (el_ge(close[kk] - open[kk], close[kk + 1] - open[kk + 1])) shrinkUp = false;
        if (el_ge(open[kk] - close[kk], open[kk + 1] - close[kk + 1])) shrinkDown = false;
    }
}
